import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        DataOutputStream dos = new DataOutputStream(System.out);
        int n = readInt(dis);
        int B = readInt(dis);
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = readInt(dis);
        }
        int evenCount = 0, oddCount = 0;
        ArrayList<Integer> differences = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            if (a[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            if (evenCount == oddCount) {
                differences.add(Math.abs(a[i] - a[i + 1]));
            }
        }
        Collections.sort(differences);
        int total = 0, count = 0;
        for (int diff : differences) {
            total += diff;
            if (total > B) break;
            count++;
        }
        writeInt(dos, count);
        dos.flush();
        dis.close();
        dos.close();
    }

    static int readInt(DataInputStream dis) throws IOException {
        int num = 0;
        int sign = 1;
        int c = dis.read();
        while (c <= ' ') c = dis.read();
        if (c == '-') {
            sign = -1;
            c = dis.read();
        }
        while (c >= '0' && c <= '9') {
            num = num * 10 + c - '0';
            c = dis.read();
        }
        return num * sign;
    }

    static void writeInt(DataOutputStream dos, int val) throws IOException {
        dos.writeBytes(Integer.toString(val));
        dos.writeByte('\n');
    }
}
